INSERT INTO content_errors (job_id, severity, error_code, error_message, recoverable, context)
SELECT NULLIF('{{$json.job_id}}','')::uuid, 'warning', 'QA_PARSE_WARNING', COALESCE(NULLIF('{{$json.warning_message_sql}}',''),'LLM response parse warning'), true, jsonb_build_object('raw_text', LEFT('{{$json.raw_model_text_sql}}', 2000), 'workflow', '{{$json.current_stage_sql}}')
WHERE COALESCE('{{$json.parse_warning}}','false') = 'true';

UPDATE content_jobs SET status='qa_in_progress', updated_at=now() WHERE id=NULLIF('{{$json.job_id}}','')::uuid;
UPDATE content_outputs SET qa_status='needs_human_review', updated_at=now() WHERE job_id=NULLIF('{{$json.job_id}}','')::uuid AND qa_status='pending';
INSERT INTO content_outputs (job_id, output_type, title, structured_data, qa_status) VALUES (NULLIF('{{$json.job_id}}','')::uuid, 'qa_report', 'QA report', COALESCE(NULLIF('{{$json.qa_report_json_sql}}',''),'{}')::jsonb, 'needs_human_review');
UPDATE content_jobs SET status='waiting_for_human_review', updated_at=now() WHERE id=NULLIF('{{$json.job_id}}','')::uuid;
INSERT INTO content_events (job_id,event_type,message,metadata) VALUES (NULLIF('{{$json.job_id}}','')::uuid,'approval_gate','Final delivery approval gate reached',jsonb_build_object('approval_stage','final_delivery','human_only',true));
SELECT NULLIF('{{$json.job_id}}','') AS job_id, 'waiting_for_human_review' AS status;

WITH outputs AS (
  SELECT COALESCE(jsonb_agg(jsonb_build_object('output_type', output_type, 'title', title, 'qa_status', qa_status, 'structured_data', structured_data) ORDER BY created_at), '[]'::jsonb) AS included_outputs
  FROM content_outputs WHERE job_id=NULLIF('{{$json.job_id}}','')::uuid AND output_type <> 'delivery_pack'
), pack AS (
  INSERT INTO content_outputs (job_id, output_type, title, structured_data, qa_status, drive_file_id)
  VALUES (NULLIF('{{$json.job_id}}','')::uuid, 'delivery_pack', 'Human-approved delivery pack', jsonb_build_object('delivery_ready',true,'generated_after_human_approval',true,'included_outputs',(SELECT included_outputs FROM outputs),'drive_upload_response',COALESCE(NULLIF('{{$json.id}}',''),'')), 'passed', NULLIF('{{$json.id}}',''))
  RETURNING id
), event_insert AS (
  INSERT INTO content_events (job_id,event_type,message,metadata)
  VALUES (NULLIF('{{$json.job_id}}','')::uuid,'delivery_pack_ready','Delivery pack created after final human approval',jsonb_build_object('delivery_pack_id',(SELECT id FROM pack)))
)
UPDATE content_jobs SET status='delivery_ready', updated_at=now() WHERE id=NULLIF('{{$json.job_id}}','')::uuid;
SELECT NULLIF('{{$json.job_id}}','') AS job_id, 'delivery_ready' AS status, (SELECT id::text FROM pack) AS delivery_pack_id;

